import json, sys, hashlib
from common import *
d = make_copy("walk_main")
show("fresh freeze in copy", run(d, "good", script="freeze_cli.py"), 1)
h0 = hashlib.sha256((d/"reports/freeze_manifest.json").read_bytes()).hexdigest()
p = run(d, "good", "--run"); show("1. --run with no marker", p, 1); print("    hash printed:", "Manifest SHA-256" in p.stdout); state(d)
marker(d, "options")
p = run(d, "good", "--run"); show("2. options marker, Step A", p, 3); state(d); print("    hash printed before Step A line:", p.stdout.find("Manifest SHA") < p.stdout.find("Step A:"), "| same as manifest:", h0 in p.stdout)
p = run(d, "crash", "--run"); show("3. Step A crash on repeat", p, 2); rec = state(d); print("    error in record:", rec["attempts"][-1].get("error"))
show("4. rerun, no note", run(d, "good", "--run"), 1)
with open(d/"build_series.py", "a") as f: f.write("\n# crash fix\n")
with open(d/"PROTOCOL.md", "a") as f: f.write("\ncrash fix logged\n")
show("5. rerun with note, code changed, no refreeze", run(d, "good", "--run", "--crash-fix-note", "fixed reader"), 1)
show("6. normal freeze after unlock", run(d, "good", script="freeze_cli.py"), 1)
show("7. --after-crash with blank note", run(d, "good", "--after-crash", "  ", script="freeze_cli.py"), 1)
show("8. --after-crash with note", run(d, "good", "--after-crash", "Fixed the reader", script="freeze_cli.py"), 2); rec = state(d); print("    refreeze entry keys:", list(rec["refreezes"][0]), "| old is h0:", rec["refreezes"][0]["old_sha256"] == h0)
p = run(d, "good", "--run", "--crash-fix-note", "fixed reader"); show("9. rerun with note", p, 2); rec = state(d); print("    attempts:", [(a.get("crash_fix_note"), a["manifest_sha256"][:8], "error" in a) for a in rec["attempts"]])
marker(d, "outcomes")
p = run(d, "wrongmap", "--run"); show("10. Step B input stop", p, 2); rec = state(d); print("    error:", rec["attempts"][-1]["error"][:120])
show("11. rerun, no note", run(d, "good", "--run"), 1)
show("12. accept after input stop", run(d, "good", "--run", "--accept-floor-failure"), 1)
p = run(d, "good", "--run", "--crash-fix-note", "fixed the map"); show("13. rerun with note, full", p, 5); rec = state(d)
res = json.loads((d/"reports/stage5_result.json").read_text()); print("    result keys:", list(res)); print("    result hash = attempt hash:", res["manifest_sha256"] == rec["attempts"][-1]["manifest_sha256"]); print("    line printed:", res["line"] in p.stdout, "| disclosure printed:", res["disclosure"] in p.stdout, "| line before disclosure:", p.stdout.find(res["line"]) < p.stdout.find(res["disclosure"]))
print("    frames:", sorted(x.name for x in (d/"data/test").iterdir()))
show("14. repeat, no note", run(d, "good", "--run"), 1)
show("15. repeat, with note", run(d, "good", "--run", "--crash-fix-note", "again"), 1)
show("16. repeat, accept", run(d, "good", "--run", "--accept-floor-failure"), 1)
show("17. after-crash after result", run(d, "good", "--after-crash", "x", script="freeze_cli.py"), 1)
show("18. normal freeze after result", run(d, "good", script="freeze_cli.py"), 1)
print("    manifest unchanged after refusals:", rec["refreezes"][-1]["new_sha256"] == hashlib.sha256((d/"reports/freeze_manifest.json").read_bytes()).hexdigest())
